"""Reference-aware VCF reading, normalization and writing.

Public API:

- :class:`VcfHeader` — the ``##`` meta-information lines (kept verbatim
  and in order) together with the sample names declared by the single
  ``#CHROM`` column header.
- :class:`VcfRecord` — one VCF data row: the eight fixed columns, an
  optional ``FORMAT`` column and the per-sample text columns.
- :class:`VcfFile` — a parsed VCF document pairing a header with its
  records.
- :func:`read_vcf` — parse VCF text from a path or text stream.
- :func:`normalize_record` / :func:`normalize_vcf` — trim common
  allele suffixes/prefixes and left-align indels against a reference.
- :func:`render_vcf` / :func:`write_vcf` — serialize a VCF document
  with tabs and ``"\\n"``.

Ordinary sequence alleles only contain the IUPAC DNA symbols
``ACGTRYSWKMBDHVN`` (lower-case input is upper-cased).  Records carrying
symbolic (``<...>``), break-end (brackets or a ``.`` join), spanning
(``*``) or missing (``.``) ALT alleles are validated against the
reference but never trimmed or shifted.
"""

from __future__ import annotations

import io
import os
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass, replace

from .sequence_io import SequenceRecord, _VALID_BASES

__all__ = [
    "VcfHeader",
    "VcfRecord",
    "VcfFile",
    "VcfFormatError",
    "ReferenceMismatchError",
    "read_vcf",
    "normalize_record",
    "normalize_vcf",
    "render_vcf",
    "write_vcf",
]

_FIXED_COLUMNS = ("#CHROM", "POS", "ID", "REF", "ALT", "QUAL", "FILTER", "INFO")
_MIN_COLUMNS = 8


class VcfFormatError(ValueError):
    """Malformed VCF input (missing/duplicate header, bad columns or fields)."""


class ReferenceMismatchError(ValueError):
    """A record's CHROM is absent/duplicated in the reference or REF disagrees."""


@dataclass(frozen=True)
class VcfHeader:
    """The VCF header.

    ``meta_lines`` holds the ``##`` meta-information lines verbatim,
    without their line terminators and in input order.  ``samples``
    holds the sample names taken from the single ``#CHROM`` header line
    (an empty tuple for sample-less VCF).
    """

    meta_lines: tuple[str, ...] = ()
    samples: tuple[str, ...] = ()

    @property
    def column_names(self) -> tuple[str, ...]:
        """All column names as declared by the ``#CHROM`` line."""
        if self.samples:
            return _FIXED_COLUMNS + ("FORMAT",) + self.samples
        return _FIXED_COLUMNS


@dataclass(frozen=True)
class VcfRecord:
    """One VCF data row.

    The fixed columns are ``chrom``, ``pos`` (1-based), ``id``, ``ref``,
    ``alt`` (a tuple of ALT allele strings), ``qual``, ``filter`` and
    ``info``.  For a VCF with samples, ``format_text`` holds the FORMAT
    string and ``sample_text`` one verbatim column per sample; both are
    empty for sample-less VCF.  ``line_number`` is the 1-based source
    line of a parsed record (``0`` for records built directly).
    """

    chrom: str
    pos: int
    id: str
    ref: str
    alt: tuple[str, ...]
    qual: str
    filter: str
    info: str
    format_text: str | None = None
    sample_text: tuple[str, ...] = ()
    line_number: int = 0

    @property
    def alt_text(self) -> str:
        """The ALT column as it appears on disk."""
        return ",".join(self.alt)


@dataclass(frozen=True)
class VcfFile:
    """A parsed VCF document: a header and its records in input order.

    ``source`` is the path or stream label the document was read from
    and is used to qualify error messages during normalization.
    """

    header: VcfHeader
    records: tuple[VcfRecord, ...] = ()
    source: str = ""


def _line_error(source: str, line_number: int, message: str) -> VcfFormatError:
    return VcfFormatError(f"{source}:{line_number}: {message}")


def _is_plain_allele(allele: str) -> bool:
    """Whether *allele* is an ordinary sequence allele of real bases.

    The gVCF spanning value ``*``, the missing value ``.``, symbolic
    alleles (``<DEL>``) and break-end alleles (``]chr:123]N``, ``N.``)
    are not plain.
    """
    if not allele or allele == "*" or allele == ".":
        return False
    if "<" in allele or ">" in allele:
        return False
    if "[" in allele or "]" in allele or "." in allele or "*" in allele:
        return False
    return True


def _validate_allele(allele: str) -> str:
    """Upper-case and validate one ordinary sequence allele."""
    upper = allele.upper()
    for offset, symbol in enumerate(upper):
        if symbol not in _VALID_BASES:
            raise ValueError(
                f"invalid allele symbol {symbol!r} at offset {offset} of {allele!r}"
            )
    return upper


def _parse_pos(pos_text: str, source: str, number: int) -> int:
    if not pos_text or any(char < "0" or char > "9" for char in pos_text):
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        )
    pos = int(pos_text)
    if pos <= 0:
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        )
    return pos


def _parse_record_line(
    line: str, number: int, source: str, samples: Sequence[str]
) -> VcfRecord:
    fields = line.split("\t")
    if len(fields) < _MIN_COLUMNS:
        raise _line_error(
            source,
            number,
            f"expected at least 8 tab-separated columns, got {len(fields)}",
        )
    if samples:
        expected = _MIN_COLUMNS + 1 + len(samples)
        if len(fields) != expected:
            raise _line_error(
                source,
                number,
                f"expected {expected} columns to match the #CHROM header, got {len(fields)}",
            )
        format_text = fields[8]
        if not format_text:
            raise _line_error(source, number, "empty FORMAT column")
        sample_text = tuple(fields[9:])
    else:
        if len(fields) != _MIN_COLUMNS:
            raise _line_error(
                source,
                number,
                f"expected 8 columns to match the sample-less #CHROM header, "
                f"got {len(fields)}",
            )
        format_text = None
        sample_text = ()

    chrom, pos_text, ident, ref_text, alt_text, qual, flt, info = fields[:8]

    if not chrom:
        raise _line_error(source, number, "empty CHROM column")
    pos = _parse_pos(pos_text, source, number)

    if not ref_text:
        raise _line_error(source, number, "empty REF allele")
    try:
        ref = _validate_allele(ref_text)
    except ValueError as exc:
        raise _line_error(source, number, str(exc)) from None

    if not alt_text:
        raise _line_error(source, number, "empty ALT column")
    alts: list[str] = []
    for allele in alt_text.split(","):
        if allele == "":
            raise _line_error(source, number, "empty ALT allele")
        if not _is_plain_allele(allele):
            alts.append(allele)
            continue
        try:
            alts.append(_validate_allele(allele))
        except ValueError as exc:
            raise _line_error(source, number, str(exc)) from None

    return VcfRecord(
        chrom=chrom,
        pos=pos,
        id=ident,
        ref=ref,
        alt=tuple(alts),
        qual=qual,
        filter=flt,
        info=info,
        format_text=format_text,
        sample_text=sample_text,
        line_number=number,
    )


def _parse_header_line(
    line: str, number: int, source: str
) -> tuple[str, ...]:
    """Validate the ``#CHROM`` line and return its sample names."""
    columns = line.split("\t")
    if tuple(columns[:8]) != _FIXED_COLUMNS:
        raise _line_error(
            source,
            number,
            "the first eight #CHROM header columns must be exactly "
            "#CHROM\\tPOS\\tID\\tREF\\tALT\\tQUAL\\tFILTER\\tINFO",
        )
    tail = columns[8:]
    if not tail:
        return ()
    if tail[0] != "FORMAT":
        raise _line_error(
            source, number, "the ninth column, when present, must be FORMAT"
        )
    samples = tuple(tail[1:])
    if not samples:
        raise _line_error(source, number, "FORMAT column requires at least one sample")
    if any(not sample for sample in samples):
        raise _line_error(source, number, "empty sample name in #CHROM header")
    return samples


def read_vcf(
    source: "str | os.PathLike[str] | io.TextIOBase",
) -> VcfFile:
    """Read and validate a whole VCF document from *source*.

    *source* is either a filesystem path (``str`` or :class:`os.PathLike`)
    or an already-open text stream.  ``##`` meta-information lines are
    kept verbatim and in order; exactly one legal ``#CHROM`` line is
    required and every data row must match its columns.  Records are
    returned in input order.

    Raises :class:`VcfFormatError` for malformed input and :class:`OSError`
    when opening a path fails.
    """
    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        meta_lines: list[str] = []
        samples: tuple[str, ...] | None = None
        records: list[VcfRecord] = []

        for number, raw_line in enumerate(stream, start=1):
            line = raw_line.rstrip("\r\n")
            if line.startswith("##"):
                if samples is not None:
                    raise _line_error(
                        source_name,
                        number,
                        "meta-information line after the #CHROM header",
                    )
                meta_lines.append(line)
            elif line.startswith("#"):
                if samples is not None:
                    raise _line_error(
                        source_name, number, "duplicate #CHROM column header"
                    )
                samples = _parse_header_line(line, number, source_name)
            else:
                if samples is None:
                    raise _line_error(
                        source_name, number, "data row before the #CHROM column header"
                    )
                records.append(
                    _parse_record_line(line, number, source_name, samples)
                )

        if samples is None:
            raise VcfFormatError(
                f"{source_name}:1: missing #CHROM column header"
            )
        return VcfFile(
            VcfHeader(tuple(meta_lines), samples), tuple(records), source_name
        )
    finally:
        if close:
            stream.close()


def _build_reference(
    reference: Iterable[SequenceRecord],
) -> tuple[dict[str, str], set[str]]:
    """Map CHROM to sequence, tracking identifiers appearing more than once."""
    sequences: dict[str, str] = {}
    duplicates: set[str] = set()
    for record in reference:
        if record.identifier in sequences:
            duplicates.add(record.identifier)
        else:
            sequences[record.identifier] = record.sequence
    return sequences, duplicates


def _record_error(source: str, record: VcfRecord, message: str) -> VcfFormatError:
    if source and record.line_number:
        return VcfFormatError(f"{source}:{record.line_number}: {message}")
    if record.line_number:
        return VcfFormatError(f"line {record.line_number}: {message}")
    return VcfFormatError(message)


def _resolve_chromosome(
    record: VcfRecord,
    sequences: Mapping[str, str],
    duplicates: set[str],
) -> str:
    if record.chrom in duplicates:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: CHROM occurs more than once "
            "in the reference"
        )
    try:
        return sequences[record.chrom]
    except KeyError:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: no matching record in the reference"
        ) from None


def _minimize(
    pos: int, ref: str, alts: Sequence[str]
) -> tuple[int, str, tuple[str, ...]]:
    """Remove the common suffix and prefix shared by all alleles.

    At least one base is always retained per allele and *pos* (1-based)
    is advanced by the number of stripped leading bases.
    """
    # Common suffix: compare each ALT against REF up to the shorter
    # length, always leaving at least one base per allele.
    suffix = 0
    while True:
        index = len(ref) - 1 - suffix
        if index <= 0:
            break
        ref_base = ref[index]
        ok = True
        for alt in alts:
            alt_index = len(alt) - 1 - suffix
            if alt_index <= 0 or alt[alt_index] != ref_base:
                ok = False
                break
        if not ok:
            break
        suffix += 1
    if suffix:
        ref = ref[: len(ref) - suffix]
        alts = tuple(alt[: len(alt) - suffix] for alt in alts)

    # Common prefix: at least one base must remain in every allele.
    prefix = 0
    shortest = min(len(ref), min(len(alt) for alt in alts))
    while prefix < shortest - 1 and all(
        alt[prefix] == ref[prefix] for alt in alts
    ):
        prefix += 1
    if prefix:
        ref = ref[prefix:]
        alts = tuple(alt[prefix:] for alt in alts)
        pos += prefix

    return pos, ref, tuple(alts)


def _lengths_differ(ref: str, alts: Sequence[str]) -> bool:
    return any(len(alt) != len(ref) for alt in alts)


def _normalize_against(
    record: VcfRecord,
    sequences: Mapping[str, str],
    duplicates: set[str],
    source: str,
) -> VcfRecord:
    chromosome = _resolve_chromosome(record, sequences, duplicates)

    end = record.pos - 1 + len(record.ref)
    if record.pos < 1 or end > len(chromosome):
        raise _record_error(
            source,
            record,
            f"CHROM {record.chrom} POS {record.pos}: REF of length {len(record.ref)} "
            f"is out of bounds for a reference of length {len(chromosome)}",
        )

    expected = chromosome[record.pos - 1 : end].upper()
    if expected != record.ref:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: REF does not match the "
            f"reference: expected {expected!r}, found {record.ref!r}"
        )

    if not all(_is_plain_allele(allele) for allele in record.alt):
        # Symbolic, break-end, spanning or missing ALT: verify only.
        return record

    pos, ref, alts = _minimize(record.pos, record.ref, record.alt)

    # Left-align: prepend the preceding reference base to every allele
    # and re-minimize.  A move only happens when re-minimization removes
    # a (different) right-hand base, i.e. the extended window represents
    # the same haplotypes; once a step leaves the alleles unchanged the
    # minimum POS has been reached.
    while pos > 1 and _lengths_differ(ref, alts):
        preceding = chromosome[pos - 2].upper()
        next_pos, next_ref, next_alts = _minimize(
            pos - 1,
            preceding + ref,
            tuple(preceding + alt for alt in alts),
        )
        if (next_pos, next_ref, next_alts) == (pos, ref, alts):
            break
        pos, ref, alts = next_pos, next_ref, next_alts

    return replace(record, pos=pos, ref=ref, alt=alts)


def normalize_record(
    record: VcfRecord,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfRecord:
    """Normalize one record against *reference*.

    *reference* is either a mapping of CHROM to upper-case reference
    sequence or an iterable of :class:`~genome_variant.sequence_io.SequenceRecord`
    (duplicate identifiers raise :class:`ReferenceMismatchError`).

    The REF fragment at POS is always verified.  Records whose ALT
    contains a symbolic, break-end, spanning (``*``) or missing (``.``)
    allele are returned unchanged.  Otherwise all sequence alleles are
    trimmed of their shared suffix and prefix (one base is always kept)
    and, when allele lengths differ, left-shifted across repeated
    reference bases to the smallest POS representing the same
    haplotypes, re-minimizing after every shift.  ID, QUAL, FILTER,
    INFO, FORMAT, sample text and ALT order are preserved.

    Raises :class:`ReferenceMismatchError` for an absent/duplicate CHROM
    or a REF that disagrees with the reference, and
    :class:`VcfFormatError` for a record that runs past the reference.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences, duplicates = _build_reference(reference)
    return _normalize_against(record, sequences, duplicates, "")


def normalize_vcf(
    document: VcfFile,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfFile:
    """Normalize every record of *document* against *reference*.

    Record order is preserved; see :func:`normalize_record` for the
    per-record rules.  Every record is validated before the normalized
    document is returned, so an error never comes with partial output.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences, duplicates = _build_reference(reference)

    normalized = tuple(
        _normalize_against(record, sequences, duplicates, document.source)
        for record in document.records
    )
    return VcfFile(document.header, normalized, document.source)


def _record_line(record: VcfRecord) -> str:
    fields = [
        record.chrom,
        str(record.pos),
        record.id,
        record.ref,
        record.alt_text,
        record.qual,
        record.filter,
        record.info,
    ]
    if record.format_text is not None:
        fields.append(record.format_text)
        fields.extend(record.sample_text)
    return "\t".join(fields)


def render_vcf(document: VcfFile) -> str:
    """Serialize *document* to VCF text.

    Output uses tabs and ``"\\n"`` line endings and always ends with
    exactly one trailing newline; a record-less VCF still writes the
    complete header (``##`` lines followed by the ``#CHROM`` line).
    """
    lines = list(document.header.meta_lines)
    lines.append("\t".join(document.header.column_names))
    lines.extend(_record_line(record) for record in document.records)
    return "\n".join(lines) + "\n"


def write_vcf(
    document: VcfFile,
    output: "str | os.PathLike[str] | io.TextIOBase",
) -> None:
    """Write *document* to *output* as VCF text.

    Tabs and ``"\\n"`` are used throughout with exactly one trailing
    newline; an empty-record VCF still writes the complete header.
    """
    text = render_vcf(document)
    if isinstance(output, io.IOBase):
        output.write(text)
    elif isinstance(output, (str, os.PathLike)):
        with open(os.fspath(output), "w", encoding="utf-8", newline="") as stream:
            stream.write(text)
    else:
        raise TypeError("output must be a text path or a text stream")

"""Multi-sample variant summarization.

Public API:

- :class:`ManifestError` — malformed manifest text, bad fields, duplicate
  sample names, or a sample VCF that fails structural/genotype validation.
- :func:`read_manifest` — parse a JSON Lines manifest into
  :class:`ManifestEntry` objects in file order.
- :func:`summarize_variants` — read one single-sample VCF per manifest
  entry, normalize the calls against a reference and merge equivalent
  calls into :class:`VariantSummary` objects.

The manifest is JSON Lines: each non-empty line is a JSON object with a
non-empty, tab-free, globally unique ``sample`` and a ``vcf`` path to a
single-sample VCF.  Relative VCF paths in a file manifest resolve
against the manifest's own directory; relative paths in a stream manifest
resolve against the current working directory.

Each VCF must declare exactly one sample, whose name matches its manifest
``sample``; every record must carry a single ordinary sequence ALT, a
``PASS``/``.`` FILTER and the fields ``GT``, ``DP`` and ``AD``.  Genotypes
are restricted to ``0/1`` and ``1/1``; DP is a non-negative integer and
the two AD values are non-negative integers summing to DP.
"""

from __future__ import annotations

import io
import json
import os
from collections.abc import Iterable, Sequence
from dataclasses import dataclass

from .sequence_io import SequenceRecord, read_sequences
from .vcf import (
    VcfFormatError,
    VcfRecord,
    _is_plain_allele,
    normalize_vcf,
    read_vcf,
)

__all__ = [
    "ManifestError",
    "ManifestEntry",
    "VariantSummary",
    "SampleCall",
    "read_manifest",
    "summarize_variants",
    "render_summaries",
]

#: Genotypes accepted from the FORMAT/GT field, with allele contribution.
_GENOTYPES = {"0/1": 1, "1/1": 2}


class ManifestError(ValueError):
    """The manifest or one of its single-sample VCFs is invalid."""


@dataclass(frozen=True)
class ManifestEntry:
    """One manifest row: its 1-based line, a unique ``sample`` and ``vcf``."""

    line_number: int
    sample: str
    vcf: str


@dataclass(frozen=True)
class VariantSummary:
    """One merged variant line.

    ``ref_index`` is the zero-based position of the variant's CHROM in the
    reference input.  ``samples`` holds one :class:`SampleCall` per actual
    caller in manifest order.
    """

    ref_index: int
    chrom: str
    pos: int
    ref: str
    alt: str
    samples: tuple[SampleCall, ...]

    @property
    def sample_count(self) -> int:
        """Number of samples with the variant called."""
        return len(self.samples)

    @property
    def ref_order_key(self) -> tuple:
        """Sorting key: reference order, then POS, REF, ALT."""
        return (self.ref_index, self.pos, self.ref, self.alt)

    @property
    def allele_count(self) -> int:
        """Sum of alt alleles (one for ``0/1``, two for ``1/1``)."""
        return sum(call.alleles for call in self.samples)

    @property
    def depth(self) -> int:
        """Sum of the per-sample DP values."""
        return sum(call.dp for call in self.samples)


@dataclass(frozen=True)
class SampleCall:
    """One sample's call at a merged variant: ``sample``, GT, DP, AD."""

    sample: str
    gt: str
    dp: int
    ad: tuple[int, int]

    @property
    def alleles(self) -> int:
        """Alt allele count for this genotype (``0/1`` -> 1, ``1/1`` -> 2)."""
        return _GENOTYPES[self.gt]


def read_manifest(
    source: "str | os.PathLike[str] | io.TextIOBase",
) -> tuple[ManifestEntry, ...]:
    """Parse a whole JSON Lines manifest from *source*.

    *source* is either a filesystem path (``str`` or :class:`os.PathLike`)
    or an already-open text stream.  Blank lines are ignored; every other
    line must decode to a JSON object containing exactly the string fields
    ``sample`` (non-empty, tab-free, unique) and ``vcf``.

    Relative ``vcf`` values resolve against the manifest file's directory
    for a path source, or against the current working directory for a
    stream source.

    Raises :class:`ManifestError` carrying the 1-based manifest line
    number on any structural or field violation, and :class:`OSError`
    when opening a path fails.
    """
    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        base_dir = os.getcwd()
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        base_dir = os.path.dirname(os.path.abspath(path))
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        seen: set[str] = set()
        entries: list[ManifestEntry] = []

        for number, raw_line in enumerate(stream, start=1):
            line = raw_line.rstrip("\r\n")
            if not line.strip():
                continue
            try:
                value = json.loads(line)
            except json.JSONDecodeError as exc:
                raise ManifestError(
                    f"{source_name}:{number}: invalid JSON: {exc.msg}"
                ) from None
            if not isinstance(value, dict):
                raise ManifestError(
                    f"{source_name}:{number}: manifest line must be a JSON object"
                )
            if set(value) != {"sample", "vcf"}:
                raise ManifestError(
                    f"{source_name}:{number}: manifest line must contain exactly "
                    "the fields sample and vcf"
                )
            sample = value["sample"]
            vcf = value["vcf"]
            if not isinstance(sample, str) or not sample or "\t" in sample:
                raise ManifestError(
                    f"{source_name}:{number}: sample must be a non-empty string "
                    "without tab characters"
                )
            if not isinstance(vcf, str) or not vcf:
                raise ManifestError(
                    f"{source_name}:{number}: vcf must be a non-empty string path"
                )
            if sample in seen:
                raise ManifestError(
                    f"{source_name}:{number}: duplicate sample {sample!r}"
                )
            seen.add(sample)
            resolved = vcf if os.path.isabs(vcf) else os.path.join(base_dir, vcf)
            entries.append(ManifestEntry(number, sample, resolved))

        return tuple(entries)
    finally:
        if close:
            stream.close()


def _record_error(source: str, record: VcfRecord, message: str) -> ManifestError:
    if source and record.line_number:
        return ManifestError(f"{source}:{record.line_number}: {message}")
    if record.line_number:
        return ManifestError(f"line {record.line_number}: {message}")
    return ManifestError(message)


def _non_negative_int(text: str) -> int:
    """Parse *text* as a non-negative integer without a sign or spaces."""
    if not text or any(char < "0" or char > "9" for char in text):
        raise ValueError("not a non-negative integer")
    return int(text)


def _validate_and_extract(
    record: VcfRecord, source: str
) -> tuple[str, int, tuple[int, int]]:
    """Validate one record and return ``(gt, dp, ad)`` from its sample text."""
    if len(record.alt) != 1:
        raise _record_error(
            source,
            record,
            f"expected exactly one ALT allele, got {len(record.alt)}",
        )
    alt = record.alt[0]
    if not _is_plain_allele(alt):
        raise _record_error(
            source, record, "ALT must be a single ordinary sequence allele"
        )
    if record.filter not in ("PASS", "."):
        raise _record_error(
            source, record, f"FILTER must be PASS or '.', got {record.filter!r}"
        )
    if record.format_text is None:
        raise _record_error(source, record, "missing FORMAT column")

    format_fields = record.format_text.split(":")
    if len(format_fields) != len(set(format_fields)):
        raise _record_error(source, record, "FORMAT contains duplicate field IDs")
    required = ("GT", "DP", "AD")
    missing = [field for field in required if field not in format_fields]
    if missing:
        raise _record_error(
            source,
            record,
            "FORMAT must contain GT, DP and AD; missing " + ",".join(missing),
        )

    if len(record.sample_text) != 1:
        raise _record_error(source, record, "expected one sample column")
    values = record.sample_text[0].split(":")
    if len(values) != len(format_fields):
        raise _record_error(
            source,
            record,
            f"sample has {len(values)} fields but FORMAT lists {len(format_fields)}",
        )
    data = dict(zip(format_fields, values))

    gt = data["GT"]
    if gt not in _GENOTYPES:
        raise _record_error(
            source, record, f"GT must be 0/1 or 1/1, got {gt!r}"
        )

    try:
        dp = _non_negative_int(data["DP"])
    except ValueError:
        raise _record_error(
            source, record, f"DP must be a non-negative integer, got {data['DP']!r}"
        ) from None

    ad_fields = data["AD"].split(",")
    if len(ad_fields) != 2:
        raise _record_error(
            source,
            record,
            f"AD must contain exactly two values, got {len(ad_fields)}",
        )
    ad: list[int] = []
    for field in ad_fields:
        try:
            ad.append(_non_negative_int(field))
        except ValueError:
            raise _record_error(
                source,
                record,
                f"AD values must be non-negative integers, got {field!r}",
            ) from None
    if ad[0] + ad[1] != dp:
        raise _record_error(
            source,
            record,
            f"AD values must sum to DP ({dp}), got {ad[0]}+{ad[1]}",
        )

    return gt, dp, (ad[0], ad[1])


def summarize_variants(
    manifest: "str | os.PathLike[str] | io.TextIOBase | Sequence[ManifestEntry]",
    reference: "str | os.PathLike[str] | io.TextIOBase | Iterable[SequenceRecord]",
) -> tuple[VariantSummary, ...]:
    """Summarize the manifest's VCFs into merged variant lines.

    *manifest* is a manifest path/stream or an already-parsed sequence of
    :class:`ManifestEntry`; *reference* is a FASTA path/stream or an
    iterable of :class:`~genome_variant.sequence_io.SequenceRecord`.
    Relative VCF paths are resolved as described for :func:`read_manifest`.

    Every VCF is read, structurally and genotypically validated and
    normalized against the reference; equivalent calls (same normalized
    ``CHROM``, ``POS``, ``REF``, ``ALT``) are then merged across samples.
    Two records in one VCF normalizing to the same key are a data error.

    Returns summaries ordered by reference record order, then POS, REF and
    ALT; each summary's ``samples`` follow manifest order.

    Raises :class:`ManifestError` (message carries the manifest line or
    the VCF source and record line), :class:`VcfFormatError` /
    :class:`ReferenceMismatchError` for reference problems, and
    :class:`OSError` for file access failures.
    """
    if isinstance(manifest, (str, os.PathLike, io.IOBase)):
        entries = read_manifest(manifest)
    else:
        entries = tuple(manifest)

    if isinstance(reference, (str, os.PathLike, io.IOBase)):
        reference_records = tuple(read_sequences(reference, format="fasta"))
    else:
        reference_records = tuple(reference)

    # Reference order for sorting.  Every record's CHROM is checked during
    # normalization, so a later lookup only sees present (and unique) CHROMs.
    order: dict[str, int] = {}
    for index, record in enumerate(reference_records):
        order.setdefault(record.identifier, index)

    # key (chrom, pos, ref, alt) -> list of SampleCall in manifest order
    calls: dict[tuple[str, int, str, str], list[SampleCall]] = {}
    key_order: list[tuple[str, int, str, str]] = []

    for entry in entries:
        source_label = entry.vcf
        try:
            document = read_vcf(entry.vcf)
        except VcfFormatError as exc:
            raise ManifestError(str(exc)) from None

        # Single sample, named exactly as the manifest entry.
        samples = document.header.samples
        if len(samples) != 1:
            raise ManifestError(
                f"{source_label}:1: VCF must declare exactly one sample, "
                f"got {len(samples)}"
            )
        if samples[0] != entry.sample:
            raise ManifestError(
                f"{source_label}:1: sample {samples[0]!r} does not match manifest "
                f"sample {entry.sample!r}"
            )

        # Validation first (extract GT/DP/AD per record), then a single
        # reference-aware normalization of the whole document.  Records
        # map one-to-one and keep their order through normalization, so
        # the extracted data pairs back by index.
        extracted: list[tuple[str, int, tuple[int, int]]] = [
            _validate_and_extract(record, source_label) for record in document.records
        ]

        normalized = normalize_vcf(document, reference_records)

        seen_keys: set[tuple[str, int, str, str]] = set()
        for record, (gt, dp, ad) in zip(normalized.records, extracted):
            key = (record.chrom, record.pos, record.ref, record.alt[0])
            if key in seen_keys:
                raise ManifestError(
                    f"{source_label}:{record.line_number}: duplicate normalized "
                    f"variant {record.chrom}:{record.pos}:{record.ref}>{record.alt[0]}"
                )
            seen_keys.add(key)
            if key not in calls:
                calls[key] = []
                key_order.append(key)
            calls[key].append(SampleCall(entry.sample, gt, dp, ad))

    summaries: list[VariantSummary] = []
    for key in key_order:
        chrom, pos, ref, alt = key
        summaries.append(
            VariantSummary(
                ref_index=order[chrom],
                chrom=chrom,
                pos=pos,
                ref=ref,
                alt=alt,
                samples=tuple(calls[key]),
            )
        )

    summaries.sort(key=lambda summary: summary.ref_order_key)
    return tuple(summaries)


def render_summaries(summaries: Sequence[VariantSummary]) -> str:
    """Serialize *summaries* to compact UTF-8 JSON Lines text.

    Each line contains, in order, ``chrom``, ``pos``, ``ref``, ``alt``,
    ``sample_count``, ``allele_count``, ``depth`` and ``samples``; each
    sample item contains ``sample``, ``gt``, ``dp`` and ``ad`` (a
    two-element list).  Non-ASCII text is emitted verbatim and lines end
    with ``"\\n"``; an empty result is the empty string and a non-empty
    result ends with exactly one newline.
    """
    lines = []
    for summary in summaries:
        payload = {
            "chrom": summary.chrom,
            "pos": summary.pos,
            "ref": summary.ref,
            "alt": summary.alt,
            "sample_count": summary.sample_count,
            "allele_count": summary.allele_count,
            "depth": summary.depth,
            "samples": [
                {
                    "sample": call.sample,
                    "gt": call.gt,
                    "dp": call.dp,
                    "ad": [call.ad[0], call.ad[1]],
                }
                for call in summary.samples
            ],
        }
        lines.append(
            json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
        )
    return "".join(line + "\n" for line in lines)

